describe('Sauce Demo Login - Product Catalogue Access', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should successfully log in with valid credentials and redirect to product catalogue', () => {
    // Verify login form is visible
    cy.get('[data-test="login-container"]').should('be.visible');
    cy.get('[data-test="username"]').should('be.visible');
    cy.get('[data-test="password"]').should('be.visible');
    cy.get('[data-test="login-button"]').should('be.visible');

    // Enter valid credentials
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');

    // Click login button
    cy.get('[data-test="login-button"]').click();

    // Verify successful login and redirection to inventory page
    cy.url().should('include', '/inventory.html');
    cy.get('[data-test="title"]').should('contain', 'Products');

    // Verify product catalogue elements are visible
    cy.get('[data-test="inventory-container"]').should('be.visible');
    cy.get('[data-test="inventory-list"]').should('be.visible');
    cy.get('[data-test="inventory-item"]').should('have.length.greaterThan', 0);

    // Verify user is logged in by checking for inventory sidebar link
    cy.get('[data-test="inventory-sidebar-link"]').should('be.visible');
  });

  it('should display error message when logging in with invalid password', () => {
    // Enter valid username and invalid password
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('wrongpassword');

    // Click login button
    cy.get('[data-test="login-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Username and password do not match');

    // Verify user is still on login page
    cy.url().should('include', '/');
    cy.get('[data-test="login-container"]').should('be.visible');

    // Verify login button is still enabled
    cy.get('[data-test="login-button"]').should('not.be.disabled');

    // Verify no product catalogue elements are visible
    cy.get('[data-test="inventory-container"]').should('not.exist');
  });
});
